const CONFIG = {
  DEFAULT_TIMEZONE: 'America/New_York',
  TWILIO_FROM_NUMBER: '+18889839308'
};

const now = DateTime.now().setZone(CONFIG.DEFAULT_TIMEZONE);
const appts = $input.all().map(i => i.json);

function parseApptDateTime(apptDate, apptTime) {
  const dm = String(apptDate || '').trim().match(/^(\d{4})-(\d{2})-(\d{2})$/);
  const tm = String(apptTime || '').trim().match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);
  if (!dm || !tm) return null;
  const year = parseInt(dm[1], 10);
  const month = parseInt(dm[2], 10);
  const day = parseInt(dm[3], 10);
  let hour = parseInt(tm[1], 10);
  const minute = parseInt(tm[2], 10);
  const ampm = tm[3].toUpperCase();
  if (ampm === 'PM' && hour !== 12) hour += 12;
  if (ampm === 'AM' && hour === 12) hour = 0;
  return DateTime.fromObject({ year, month, day, hour, minute }, { zone: CONFIG.DEFAULT_TIMEZONE });
}

function formatFriendlyDate(ymd) {
  const m = String(ymd || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return ymd;
  const dt = DateTime.fromObject({ year: +m[1], month: +m[2], day: +m[3] }, { zone: CONFIG.DEFAULT_TIMEZONE });
  return dt.toFormat('cccc, LLLL d');
}

const nowIso = now.toISO();
const reminders = [];

for (const appt of appts) {
  const status = (appt['Status'] || '').trim();
  if (status !== 'Scheduled') continue;

  const apptDateTime = parseApptDateTime(appt['Appt Date'], appt['Appt Time']);
  if (!apptDateTime) continue;

  const hoursUntil = apptDateTime.diff(now, 'hours').hours;
  if (hoursUntil < 0) continue;

  const raw = String(appt['Phone'] || '').replace(/\D/g, '');
  const e164 = raw.length === 11 && raw.startsWith('1') ? '+' + raw
    : raw.length === 10 ? '+1' + raw : null;
  if (!e164) continue;

  const firstName = String(appt['Customer Name'] || '').trim().split(/\s+/)[0] || '';
  const greeting = firstName ? 'Hi ' + firstName + ',' : 'Hi,';
  const svc = appt['Service Type'] || 'roofing appointment';
  const dateDisplay = formatFriendlyDate(appt['Appt Date']);
  const timeDisplay = appt['Appt Time'] || '';

  const reminder24Sent = String(appt['Reminder 24h'] || '').trim();
  const reminder2Sent = String(appt['Reminder 2h'] || '').trim();

  if (!reminder24Sent && hoursUntil >= 20 && hoursUntil <= 28) {
    reminders.push({
      apptId: appt['Appt ID'],
      reminderType: '24h',
      e164Phone: e164,
      from: CONFIG.TWILIO_FROM_NUMBER,
      sentAt: nowIso,
      existingReminder24: reminder24Sent,
      existingReminder2h: reminder2Sent,
      message: greeting + ' reminder — your ' + svc + ' appointment with Valfin Tech is tomorrow, ' + dateDisplay + ' at ' + timeDisplay + '. Need to reschedule? Call us anytime.'
    });
  }
  if (!reminder2Sent && hoursUntil >= 1 && hoursUntil <= 3) {
    reminders.push({
      apptId: appt['Appt ID'],
      reminderType: '2h',
      e164Phone: e164,
      from: CONFIG.TWILIO_FROM_NUMBER,
      sentAt: nowIso,
      existingReminder24: reminder24Sent,
      existingReminder2h: reminder2Sent,
      message: greeting + ' your ' + svc + ' appointment with Valfin Tech is today at ' + timeDisplay + ' — about 2 hours from now. See you soon!'
    });
  }
}

return reminders.map(r => ({ json: r }));
